 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    markers = [value for value, _ in counts.most_common() if value != background]
    marker = markers[0]
    out = [row[:] for row in grid]

    # Join aligned markers with color 3, preserving marker cells.
    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value == marker]
        for left, right in zip(cols, cols[1:]):
            for c in range(left + 1, right):
                if grid[r][c] == background:
                    out[r][c] = 3

    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for top, bottom in zip(rows, rows[1:]):
            for r in range(top + 1, bottom):
                if grid[r][c] == background:
                    out[r][c] = 3

    return out


if __name__ == '__main__':
